  (* [comment removed for export] *)
  Lemma wr_at_of_rw_bytes_b : forall m A (bs : list byte),
    InitMem.rw_bytes_b bsegs A bs = true -> 0 <= A -> A + Z.of_nat (length bs) <= 2^64 -> wr_at bsegs m A (Z.of_nat (length bs)).
  Proof.
    intros m A bs RB HA HL. split; [exact HA|]. split; [exact HL|]. intros i Hi.
    destruct (nth_error bs (Z.to_nat i)) as [b|] eqn:E; [| apply nth_error_None in E; lia].
    pose proof (InitMem.rw_bytes_b_sound bsegs bs A (fun _ => None) RB ltac:(intros; reflexivity) HA HL (Z.to_nat i) b E) as [_ W].
    replace (A + Z.of_nat (Z.to_nat i)) with (A + i) in W by lia.
    unfold wview in *. destruct (m (wa (A + i))) as [b'|] eqn:Em; [discriminate| exact W].
  Qed.

