  (* [comment removed for export] *)
  Variable HS : mem -> Prop.
  Hypothesis HSL : hs_local HS.

  (* [comment removed for export] *)
  Lemma HS_munch_keep : forall W m m', HS m -> munch W m m' -> (forall a, AXH_LO <= a < AXH_HI -> outside W a) -> HS m'.
  Proof. intros W m m' K MU OUT. eapply HSL; [exact K|]. intros a Ha. unfold wa. apply MU. rewrite unsigned_lit by (unfold AXH_LO, AXH_HI in Ha; lia). exact (OUT a Ha). Qed.
  Lemma AXImg_munch_keep : forall W m m', AXImg m -> munch W m m' ->
    (forall a, (AXRELRO_LO <= a < AXRELRO_HI \/ AXDATA_LO <= a < AXDATA_HI) -> outside W a) -> AXImg m'.
  Proof. intros W m m' K MU OUT. eapply AXImg_agree; [exact K|]. intros a Ha. unfold wa. apply MU. rewrite unsigned_lit by (unfold AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in Ha; lia). exact (OUT a Ha). Qed.
  Lemma HS_apres_keep : forall LB SP m m', HS m -> apres H LB SP m m' -> HS m'.
  Proof. intros LB SP m m' K AP. eapply HSL; [exact K|]. intros a Ha. unfold wa. apply AP; [unfold AXH_LO, AXH_HI in Ha; lia|]. right; left. unfold aimg_client, AXH_LO, AXH_HI in *. lia. Qed.
  Lemma AXImg_apres_keep : forall LB SP m m', AXImg m -> apres H LB SP m m' -> AXImg m'.
  Proof. intros LB SP m m' K AP. eapply AXImg_agree; [exact K|]. intros a Ha. unfold wa. apply AP; [unfold AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in Ha; lia|]. right; left. unfold aimg_client, AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in *. lia. Qed.

  Lemma HS_xpres_keep : forall LB LF m1 SP XS m m', as_RFS H LF m1 -> Forall (fs_scratch H LF) XS -> HS m -> xpres H LB SP XS m m' -> HS m'.
  Proof.
    intros LB LF m1 SP XS m m' RF FX K XP. eapply HSL; [exact K|]. intros a Ha. unfold AXH_LO, AXH_HI in Ha.
    refine (proj1 (XP a ltac:(clear - Ha; lia) _)). split; [right; left; unfold aimg_client; clear - Ha; lia|].
    apply not_rin_of_Forall. eapply Forall_impl; [| exact FX]. intros iv FS. pose proof (scratch_facts H HH LF m1 [] iv RF FS) as (_ & K1 & _).
    left. unfold AIMG_TOP in K1. clear - Ha K1. lia.
  Qed.
  Lemma AXImg_xpres_keep : forall LB LF m1 SP XS m m', as_RFS H LF m1 -> Forall (fs_scratch H LF) XS -> AXImg m -> xpres H LB SP XS m m' -> AXImg m'.
  Proof.
    intros LB LF m1 SP XS m m' RF FX K XP. eapply AXImg_agree; [exact K|]. intros a Ha. unfold AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in Ha.
    refine (proj1 (XP a ltac:(clear - Ha; lia) _)). split; [right; left; unfold aimg_client; clear - Ha; lia|].
    apply not_rin_of_Forall. eapply Forall_impl; [| exact FX]. intros iv FS. pose proof (scratch_facts H HH LF m1 [] iv RF FS) as (_ & K1 & _).
    left. unfold AIMG_TOP in K1. clear - Ha K1. lia.
  Qed.
  Lemma acanary_xpres_keep : forall LB LF m1 SP XS m m', as_RFS H LF m1 -> Forall (fs_scratch H LF) XS -> acanary m -> xpres H LB SP XS m m' -> acanary m'.
  Proof.
    intros LB LF m1 SP XS m m' RF FX [can C] XP. exists can. eapply (xpres_rw_cells H); [exact XP| exact C|]. cbn [cells_size csize Nat.add].
    split; [right; left; intros a Ha; unfold aimg_client, A_STKCHK_GUARD in *; clear - Ha; lia|].
    eapply Forall_impl; [| exact FX]. intros iv FS. pose proof (scratch_facts H HH LF m1 [] iv RF FS) as (_ & K1 & _).
    left. unfold AIMG_TOP, A_STKCHK_GUARD in *. clear - K1. lia.
  Qed.
  Lemma acanary_munch_keep : forall W m m', acanary m -> munch W m m' -> wmono bsegs m m' -> disjoint_from W A_STKCHK_GUARD 8 -> acanary m'.
  Proof. intros W m m' [can CN] MU WM DJ. exists can. eapply rw_cells_transport; [exact CN | exact MU | exact WM | exact DJ]. Qed.
  (* [comment removed for export] *)
